  "data:image/jpeg;base64,";

const OPEN_VAN_IMAGE =
  "data:image/jpeg;base64,";

const MATCHED_CLOSED_VAN_IMAGE =
  "data:image/jpeg;base64,";
const MATCHED_OPEN_VAN_IMAGE =
  "data:image/jpeg;base64,";

